#include "QueueRetry.hpp"
using namespace udm;
int wmain(int argc,wchar_t**argv){if(argc!=2)return 2;fs::path root=argv[1];if(fs::exists(root))return 3;fs::create_directories(root);Json checks=Json::array();auto check=[&](bool ok,const char*n){checks.push_back({{"name",n},{"passed",ok}});};auto q=defaultQueue();q["FileRetries"]=2;Json j={{"Status","Failed"},{"QueueOrigin",true},{"QueueMember",true},{"QueueAttempts",0},{"LastHttpStatus",404}};check(!queueFailureCanRetry(q,j,true),"Legacy permanent-error behavior preserved");q["FileRetryLimitEnabled"]=true;check(queueFailureCanRetry(q,j,true),"Explicit bounded policy retries HTTP rejection");j["QueueAttempts"]=2;check(!queueFailureCanRetry(q,j,true),"Configured retry limit terminates attempts");q["FileRetryLimitEnabled"]=false;j["QueueAttempts"]=10000;check(queueFailureCanRetry(q,j,true),"Unchecked limit allows retries beyond bounded maximum");q["Enabled"]=false;check(!queueFailureCanRetry(q,j,true),"Stopped queue cannot schedule retries");q["Enabled"]=true;check(!queueFailureCanRetry(q,j,false),"Idle completed cycle cannot schedule retries");j["ProtectedRequest"]="fixture";check(!queueFailureCanRetry(q,j,true),"Protected one-shot request is not automatically replayed");j.erase("ProtectedRequest");for(auto key:{"RequiresRequestCapture","RequiresMediaCapture","AuthenticationPromptPending"}){j[key]=true;check(!queueFailureCanRetry(q,j,true),"Required browser or authentication interaction prevents blind retry");j.erase(key);}for(auto status:{401,407}){j["LastHttpStatus"]=status;check(!queueFailureCanRetry(q,j,true),"HTTP authentication rejection remains stopped after prompt dismissal");}j["LastHttpStatus"]=0;j["LastFtpStatus"]=530;check(!queueFailureCanRetry(q,j,true),"FTP authentication rejection remains stopped after prompt dismissal");j["LastFtpStatus"]=0;j["QueueMember"]=false;check(!queueFailureCanRetry(q,j,true),"Removed member cannot retry");j["QueueMember"]=true;j["Status"]="Paused";check(!queueFailureCanRetry(q,j,true),"Paused file cannot be converted into retry work");Manager m(root/L"data");auto before=m.state["Queues"];q=defaultQueue();q["FileRetryLimitEnabled"]="false";bool rejected=false;try{m.setQueue(q);}catch(...){rejected=true;}check(rejected&&m.state["Queues"]==before,"Invalid limit flag rejected atomically");bool passed=true;for(auto c:checks)passed&=yes(c,"passed");atomicText(root/L"results.json",Json{{"passed",passed},{"checks",checks}}.dump(2),false);return passed?0:1;}